style.css:
/* ===== RAiden Shogun Image Theme ===== */

/* Nền tổng thể + ảnh Raiden */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    background-image: 
        linear-gradient(
            rgba(40, 15, 80, 0.75),
            rgba(15, 5, 35, 0.85)
        ),
        url("https://i.imgur.com/3q5Qw8K.jpg");
    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;
    filter: blur(2px);
    z-index: -2;
}

/* Lớp ánh điện tím */
body::after {
    content: "";
    position: fixed;
    inset: 0;
    background: radial-gradient(
        circle at top,
        rgba(190, 130, 255, 0.25),
        transparent 60%
    );
    animation: electroPulse 6s infinite;
    pointer-events: none;
    z-index: -1;
}

@keyframes electroPulse {
    0%, 100% { opacity: 0.4; }
    50% { opacity: 0.8; }
}

/* Nội dung chính */
body, div[role="main"] {
    background: transparent !important;
    color: #eee6ff !important;
}

/* Bài viết */
div[data-pagelet^="FeedUnit"] {
    background: rgba(35, 18, 70, 0.88) !important;
    border-radius: 16px !important;
    box-shadow: 0 0 20px rgba(180, 120, 255, 0.45) !important;
    margin-bottom: 16px !important;
}

/* Thanh trên */
div[role="banner"] {
    background: linear-gradient(90deg, #3a1c6b, #6b3fcf) !important;
    box-shadow: 0 2px 18px rgba(180,120,255,0.5) !important;
}

/* Thanh bên */
div[role="navigation"],
div[aria-label="Contacts"] {
    background: rgba(20, 10, 45, 0.95) !important;
}

/* Link */
a {
    color: #c9a6ff !important;
}

/* Avatar & ảnh */
img {
    border-radius: 50% !important;
    box-shadow: 0 0 12px rgba(190, 130, 255, 0.5) !important;
}
